# POST /api/sheets/{sheetId}/generate-plans — for every plan on the sheet, in the order they were added,
# add a DRAFT claim of its amount for every plan date up to its end and the sheet's today that it has made
# none for yet, by the claim form's rules (a refused date is skipped, and tried again next time).
# Responds with how many were made.
# Refused on an archived sheet; a viewer may make none, so for a viewer nothing is written and none are counted.
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: generate
generate:
  class: net.officefloor.hq.app.plan.GeneratePlanClaims
  govern: [ transaction ]
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.RecordRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.plan.RespondWithGenerated
# POST /api/sheets/{sheetId}/people/{personId}/plans — give the person a plan: an amount, a start date,
# every N days and an end date. An amount the claim form would refuse (or negative), a date that is not a
# date, an interval that is not a whole number of at least 1, or an end before the start, is refused.
# A viewer may change nothing: refused before anything is read or written.
guard:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: validate
validate:
  class: net.officefloor.hq.app.plan.ValidatePlan
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: add
add:
  class: net.officefloor.hq.app.plan.AddPlan
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.plan.RecordPlanAdded
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.plan.RespondWithPlan

